import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"45、【萃】 坤下兌上","description":"周易尚氏學 - 45、【萃】 坤下兌上","frontmatter":{"title":"45、【萃】 坤下兌上","description":"周易尚氏學 - 45、【萃】 坤下兌上"},"headers":[],"relativePath":"classics/shangshi/050.md","filePath":"classics/shangshi/050.md"}'),s={name:"classics/shangshi/050.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_45、【萃】-坤下兌上" tabindex="-1">45、【萃】 坤下兌上 <a class="header-anchor" href="#_45、【萃】-坤下兌上" aria-label="Permalink to “45、【萃】 坤下兌上”">​</a></h1><p>蘋聚也。坤為萬物。聚於澤中。故曰萃。王謂五。艮為廟。假格通至也。巽為人。王假有廟。言王以至誠。格於宗廟而有事也。九五得位。故曰利見大人。二五應予。故曰亨利貞。兌為羊。巽為豕。坤為牛。皆大牲。有事於宗廟用之而吉也。利有攸往。謂二應五。五天位。故傳曰順天命。</p><p>彖曰。萃。聚也。順以說。剛中而應。故聚也。王假有廟。致孝享也。利見大人亨。聚以正也。用大牲吉。利有攸往。順天命也。觀其所聚。而天地萬物之情可見矣。</p><p>五天位。巽為命。坤順。順天命。謂二順五也。艮為觀。坤為萬物。天地萬物。陰陽而已。有陰陽即有情鹹。可見而知也。</p><p>象曰。澤上於地。萃。君子以除戎器。戒不虞。</p><p>戎兵也。月令以習五戎。注五戎弓殳戈矛戰也。兌為斧鉞。艮為刀兵。除治也。君子觀於革象。因以治戎器而戒不虞。坤為亂。艮為止。止亂。故曰戒不虞。言防意外也。</p><p>初六。有孚。不終。乃亂乃萃。若號。一握為笑。勿恤。往無咎。</p><p>四有應。故曰有孚。乃初為二三所阻格。難於應四。故曰不終。乃亂乃蘋。坤為亂。為聚。言亂萃於下也。四巽為號。艮手為握。若號者。言四召初與相上下也。四下來初。則初四相握手。下卦成震。震為笑。故曰一握為笑也。坤為憂。有應故勿憂。初之四得正。故往無咎。</p><h3 id="象曰。乃亂乃萃。其志亂也。" tabindex="-1">象曰。乃亂乃萃。其志亂也。 <a class="header-anchor" href="#象曰。乃亂乃萃。其志亂也。" aria-label="Permalink to “象曰。乃亂乃萃。其志亂也。”">​</a></h3><p>坤為志為亂。</p><p>六二。引吉。無咎。孚乃利用禴。</p><p>引進也。禮檀弓。兄弟之子猶子也。蓋引而進之也。引吉無咎者。言進應五則吉而無咎也。禴薄祭也。二孚五。五兌為享。而坤為吝嗇。故曰孚乃利用禴，禴夏祭。互巽為夏也。</p><h3 id="象曰。引吉無咎。中未變也。" tabindex="-1">象曰。引吉無咎。中未變也。 <a class="header-anchor" href="#象曰。引吉無咎。中未變也。" aria-label="Permalink to “象曰。引吉無咎。中未變也。”">​</a></h3><p>進應五仍中位。故曰中未變。</p><p>六三。萃如嗟如。無攸利。往無咎。小吝。</p><p>三無應失位。而巽為嗟。故曰嗟如。巽為利。失位無應。故無所利。三前遇重陽。故往無咎。然上無應。故往小吝也。</p><h3 id="象曰。往無咎。上巽也。" tabindex="-1">象曰。往無咎。上巽也。 <a class="header-anchor" href="#象曰。往無咎。上巽也。" aria-label="Permalink to “象曰。往無咎。上巽也。”">​</a></h3><p>巽順也。上巽言上順四五。四五陽。故無咎。虞氏謂動之四故上賣。誤之遠矣。</p><p>九四。大吉無咎。</p><p>下乘三陰。故大吉。失位故無咎。無咎者僅免於咎也。</p><h3 id="象曰。大吉無咎。" tabindex="-1">象曰。大吉無咎。 <a class="header-anchor" href="#象曰。大吉無咎。" aria-label="Permalink to “象曰。大吉無咎。”">​</a></h3><p>位不當也繫辭雲。無咎者善補過者也。故無咎非全美之辭。</p><p>九五。萃有位。無咎。匪孚。元永貞。悔亡。</p><p>得位居中。故有位無咎。五孚於二。乃為四所阻。難於應二。故曰匪罕。然乾元永貞於五。居高臨下。亦無悔也。</p><h3 id="象曰。萃有位。志未光也。" tabindex="-1">象曰。萃有位。志未光也。 <a class="header-anchor" href="#象曰。萃有位。志未光也。" aria-label="Permalink to “象曰。萃有位。志未光也。”">​</a></h3><p>兌為黯昧。艮為光明。艮伏故志未光。巽為志。</p><p>上六。齎諮涕洟。無咎。</p><p>兌為口。故諮。釋文齊諮嗟嘆之辭。鄭同。馬雲。悲聲怨聲。兌為澤。故涕夷。玉篇目計出曰涕。說文。演鼻液也。上乘陽。三無應。故悲哀若是。然當位亦無大咎也。虞翻作齊資。雲齊持資膊也。即持賻助喪也。非。</p><h3 id="象曰。齊諮涕夷。未安上也。" tabindex="-1">象曰。齊諮涕夷。未安上也。 <a class="header-anchor" href="#象曰。齊諮涕夷。未安上也。" aria-label="Permalink to “象曰。齊諮涕夷。未安上也。”">​</a></h3><p>言不安於窮吝。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
